const req = $json.body;
return [{
  json: {
    ticketId: req.id || 'SRV-' + Date.now(),
    customerName: req.customerName,
    customerAddress: req.address,
    purifierModel: req.purifierModel || 'Calinfco RO+UV Alkaline',
    serviceType: req.requestType || 'Maintenance / Filter Replacement',
    preferredSlot: req.scheduledDate || 'Tomorrow 10:00 AM - 01:00 PM',
    postalCode: req.postalCode || '560001'
  }
}];
